def ensure_db_file():
    if not DB.exists():
        DB.write_bytes(zlib.decompress(base64.b64decode(INITIAL_DB_B64)))

# Chihuahua, Chihuahua uses UTC-06:00 year-round. Fixed offset avoids Windows tzdata dependency.
TZ = timezone(timedelta(hours=-6), name='America/Chihuahua')
SESSIONS = {}

DAYS_ES = ['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo']

def db():
    c = sqlite3.connect(DB)
    c.row_factory = sqlite3.Row
    return c

def hpin(pin): return hashlib.sha256(('cocopops:'+pin).encode()).hexdigest()

def required_pin_env():
    keys = {
        'ADMIN_PIN':'Dirección',
        'ITZEL_PIN':'Itzel',
        'EDUARDO_PIN':'Eduardo',
        'DIEGO_PIN':'Diego',
        'VIANNEY_PIN':'Vianney',
    }
    vals = {}
    missing = []
    for key,label in keys.items():
        v = os.getenv(key,'').strip()
        if not v:
            missing.append(key)
        elif not v.isdigit() or len(v) < 4:
            raise RuntimeError(f'{key} debe ser numérico y tener al menos 4 dígitos')
        else:
            vals[key] = v
    if missing:
        raise RuntimeError('Faltan variables de entorno obligatorias: ' + ', '.join(missing))
    return vals

def current_week(d=None):
    d = d or datetime.now(TZ).date()
    # Friday = 4
    delta = (d.weekday() - 4) % 7
    start = d - timedelta(days=delta)
    return start, start + timedelta(days=6)

def parse_iso_dt(s):
    dt = datetime.fromisoformat(s.replace('Z','+00:00'))
    if dt.tzinfo is None: dt = dt.replace(tzinfo=TZ)
    return dt.astimezone(TZ)

def local_dt_text(dt):
    return dt.astimezone(TZ).strftime('%Y-%m-%d %H:%M:%S')

def init_db():
    ensure_db_file()
    c=db(); cur=c.cursor()
    cur.executescript('''
    PRAGMA journal_mode=WAL;
    CREATE TABLE IF NOT EXISTS employees(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, pin_hash TEXT NOT NULL, active INTEGER DEFAULT 1);
    CREATE TABLE IF NOT EXISTS weekly_targets(employee_id INTEGER NOT NULL, week_start TEXT NOT NULL, target REAL NOT NULL DEFAULT 0, bonus REAL NOT NULL DEFAULT 0, PRIMARY KEY(employee_id, week_start));
    CREATE TABLE IF NOT EXISTS schedules(id INTEGER PRIMARY KEY AUTOINCREMENT, employee_id INTEGER NOT NULL, work_date TEXT NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS transactions(id INTEGER PRIMARY KEY AUTOINCREMENT, external_id TEXT UNIQUE, ts TEXT NOT NULL, amount REAL NOT NULL, status TEXT DEFAULT 'paid', source TEXT DEFAULT 'manual');
    CREATE TABLE IF NOT EXISTS daily_history(sale_date TEXT PRIMARY KEY, weekday TEXT NOT NULL, total REAL NOT NULL, transactions INTEGER DEFAULT 0);
    CREATE TABLE IF NOT EXISTS hourly_history(sale_date TEXT NOT NULL, hour INTEGER NOT NULL, total REAL NOT NULL, PRIMARY KEY(sale_date,hour));
    CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT);
    CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL, action TEXT NOT NULL, detail TEXT);
    ''')
    pins = required_pin_env()
    employees=[('Itzel',pins['ITZEL_PIN']),('Eduardo',pins['EDUARDO_PIN']),('Diego',pins['DIEGO_PIN']),('Vianney',pins['VIANNEY_PIN'])]
    for name,pin in employees:
        cur.execute('INSERT OR IGNORE INTO employees(name,pin_hash) VALUES(?,?)',(name,hpin(pin)))
        cur.execute('UPDATE employees SET pin_hash=? WHERE name=?',(hpin(pin),name))
    cur.execute("INSERT OR REPLACE INTO settings(key,value) VALUES('admin_pin_hash',?)",(hpin(pins['ADMIN_PIN']),))
    cur.execute("INSERT OR IGNORE INTO settings(key,value) VALUES('clip_endpoint','https://api-gw.payclip.com/payments')")
    c.commit(); c.close()
    seed_week_if_missing()

def seed_week_if_missing():
    ws,we=current_week()
    c=db(); cur=c.cursor()
    n=cur.execute('SELECT COUNT(*) n FROM schedules WHERE work_date BETWEEN ? AND ?',(str(ws),str(we))).fetchone()['n']
    if n: c.close(); return
    ids={r['name']:r['id'] for r in cur.execute('SELECT id,name FROM employees')}
    # defaults based on user-provided standard rota; editable in admin
    for i in range(7):
        d=ws+timedelta(days=i); wd=d.weekday()
        # Itzel Friday/Sat/Sun 13:30-21:30
        if wd in (4,5,6): cur.execute('INSERT INTO schedules(employee_id,work_date,start_time,end_time) VALUES(?,?,?,?)',(ids['Itzel'],str(d),'13:30','21:30'))
        # Eduardo Sat/Sun 13:30-21:30
        if wd in (5,6): cur.execute('INSERT INTO schedules(employee_id,work_date,start_time,end_time) VALUES(?,?,?,?)',(ids['Eduardo'],str(d),'13:30','21:30'))
        # Diego Sunday-Friday (not Saturday) 10:30-16:30
        if wd != 5: cur.execute('INSERT INTO schedules(employee_id,work_date,start_time,end_time) VALUES(?,?,?,?)',(ids['Diego'],str(d),'10:30','16:30'))
        # Vianney Monday-Saturday (not Sunday) 16:30-21:30
        if wd != 6: cur.execute('INSERT INTO schedules(employee_id,work_date,start_time,end_time) VALUES(?,?,?,?)',(ids['Vianney'],str(d),'16:30','21:30'))
    for eid in ids.values():
        cur.execute('INSERT OR IGNORE INTO weekly_targets(employee_id,week_start,target,bonus) VALUES(?,?,?,?)',(eid,str(ws),18000,0))
    c.commit(); c.close()

def auth(handler, admin=False):
    cookie=handler.headers.get('Cookie','')
    token=''
    for p in cookie.split(';'):
        if p.strip().startswith('session='): token=p.strip().split('=',1)[1]
    s=SESSIONS.get(token)
    if not s: return None
    if admin and not s.get('admin'): return None
    return s

def json_out(h,obj,status=200,cookie=None):
    b=json.dumps(obj,ensure_ascii=False).encode()
    h.send_response(status); h.send_header('Content-Type','application/json; charset=utf-8'); h.send_header('Content-Length',str(len(b)))
    if cookie: h.send_header('Set-Cookie',cookie+'; Path=/; HttpOnly; SameSite=Lax')
    h.end_headers(); h.wfile.write(b)

def read_json(h):
    n=int(h.headers.get('Content-Length','0') or 0)
    if n>2_000_000: raise ValueError('payload demasiado grande')
    return json.loads(h.rfile.read(n) or b'{}')

def day_store_total(d):
    c=db(); r=c.execute("SELECT COALESCE(SUM(amount),0) total FROM transactions WHERE status='paid' AND substr(ts,1,10)=?",(str(d),)).fetchone(); c.close(); return float(r['total'])

def employee_credit(eid, start_d, end_d=None):
    end_d=end_d or start_d
    c=db(); sched=c.execute('SELECT * FROM schedules WHERE employee_id=? AND work_date BETWEEN ? AND ? ORDER BY work_date,start_time',(eid,str(start_d),str(end_d))).fetchall()
    total=0.0; byday={}
    for s in sched:
        start=f"{s['work_date']} {s['start_time']}:00"; end=f"{s['work_date']} {s['end_time']}:59"
        r=c.execute("SELECT COALESCE(SUM(amount),0) total FROM transactions WHERE status='paid' AND ts BETWEEN ? AND ?",(start,end)).fetchone()
        v=float(r['total']); total+=v; byday[s['work_date']]=byday.get(s['work_date'],0)+v
    c.close(); return total,byday

def historical_day_context(d,current_total):
    wd=DAYS_ES[d.weekday()]
    c=db(); vals=[float(r['total']) for r in c.execute('SELECT total FROM daily_history WHERE weekday=? ORDER BY total DESC',(wd,)).fetchall()]
    allvals=[float(r['total']) for r in c.execute('SELECT total FROM daily_history ORDER BY total DESC').fetchall()]
    c.close()
    same_rank=1+sum(v>current_total for v in vals); general_rank=1+sum(v>current_total for v in allvals)
    avg=sum(vals)/len(vals) if vals else 0
    better_pct=100*sum(v<current_total for v in vals)/len(vals) if vals else 0
    higher=sorted([v for v in vals if v>current_total])
    next_gap=(higher[0]-current_total) if higher else 0
    next_target=higher[0] if higher else current_total
    record=max(vals) if vals else 0
    return {'weekday':wd,'same_rank':same_rank,'same_count':len(vals),'general_rank':general_rank,'general_count':len(allvals),'avg':avg,'vs_avg_pct':((current_total/avg-1)*100 if avg else 0),'percentile':better_pct,'next_gap':next_gap,'next_target':next_target,'record':record,'record_gap':max(0,record-current_total)}

def historical_week_rank(ws,current_total):
    c=db(); rows=c.execute('SELECT sale_date,total FROM daily_history ORDER BY sale_date').fetchall(); c.close()
    weeks={}
    for r in rows:
        d=date.fromisoformat(r['sale_date']); w,_=current_week(d); weeks[str(w)]=weeks.get(str(w),0)+float(r['total'])
    vals=sorted(weeks.values(),reverse=True)
    rank=1+sum(v>current_total for v in vals)
    higher=sorted(v for v in vals if v>current_total)
    return {'rank':rank,'count':len(vals),'record':max(vals) if vals else 0,'record_gap':max(0,(max(vals) if vals else 0)-current_total),'next_gap':(higher[0]-current_total if higher else 0)}

def historical_elapsed_projection(d, now_dt, current_total):
    # historical share sold up to the current local hour for same weekday
    wd=DAYS_ES[d.weekday()]; hr=now_dt.hour
    c=db()
    dates=[r['sale_date'] for r in c.execute('SELECT sale_date FROM daily_history WHERE weekday=?',(wd,)).fetchall()]
    ratios=[]
    for sd in dates:
        daily=c.execute('SELECT total FROM daily_history WHERE sale_date=?',(sd,)).fetchone()
        elapsed=c.execute('SELECT COALESCE(SUM(total),0) s FROM hourly_history WHERE sale_date=? AND hour<=?',(sd,hr)).fetchone()['s']
        if daily and daily['total'] and elapsed>0: ratios.append(float(elapsed)/float(daily['total']))
    c.close()
    if not ratios: return {'projection':current_total,'share':1}
    share=sum(ratios)/len(ratios)
    share=max(.05,min(1,share))
    return {'projection':current_total/share,'share':share}

def make_challenge(employee, credited, target, today_total, dayctx, week_store, weekctx):
    options=[]
    if credited < target:
        options.append((max(0,target-credited),f"Te faltan ${target-credited:,.0f} para asegurar tu Bono de Excelencia",'bonus'))
    if dayctx['next_gap']>0:
        newrank=max(1,dayctx['same_rank']-1)
        options.append((dayctx['next_gap'],f"Con ${dayctx['next_gap']:,.0f} más, hoy sube al lugar #{newrank} entre los {dayctx['same_count']} {dayctx['weekday'].lower()}s históricos",'dayrank'))
    if dayctx['record_gap']>0:
        options.append((dayctx['record_gap'],f"Faltan ${dayctx['record_gap']:,.0f} para romper el récord histórico de {dayctx['weekday'].lower()}",'record'))
    if weekctx['next_gap']>0:
        options.append((weekctx['next_gap'],f"Con ${weekctx['next_gap']:,.0f} más, esta semana sube un lugar en el ranking histórico",'weekrank'))
    if not options:
        return {'kind':'record','amount':0,'text':'¡Récord alcanzado! El siguiente reto es ampliar la marca histórica.'}
    # priority among reasonable achievable gaps, with bonus weighted strongly
    options.sort(key=lambda x: (x[0] if x[2]!='bonus' else x[0]*0.75))
    a,t,k=options[0]; return {'kind':k,'amount':a,'text':t}

def dashboard(eid):
    now=datetime.now(TZ); today=now.date(); ws,we=current_week(today)
    c=db(); emp=c.execute('SELECT id,name FROM employees WHERE id=?',(eid,)).fetchone()
    tar=c.execute('SELECT target,bonus FROM weekly_targets WHERE employee_id=? AND week_start=?',(eid,str(ws))).fetchone()
    sched=c.execute('SELECT work_date,start_time,end_time FROM schedules WHERE employee_id=? AND work_date BETWEEN ? AND ? ORDER BY work_date,start_time',(eid,str(ws),str(we))).fetchall(); c.close()
    target=float(tar['target']) if tar else 0; bonus=float(tar['bonus']) if tar else 0
    credited,byday=employee_credit(eid,ws,we); today_credit=byday.get(str(today),0)
    today_total=day_store_total(today)
    dayctx=historical_day_context(today,today_total)
    week_store=sum(day_store_total(ws+timedelta(days=i)) for i in range(7))
    weekctx=historical_week_rank(ws,week_store)
    proj=historical_elapsed_projection(today,now,today_total)
    challenge=make_challenge(emp,credited,target,today_total,dayctx,week_store,weekctx)
    pct=100*credited/target if target else 0
    return {'employee':dict(emp),'week':{'start':str(ws),'end':str(we),'target':target,'bonus':bonus,'credited':credited,'pct':pct,'remaining':max(0,target-credited),'achieved':credited>=target,'store_total':week_store,'historical':weekctx},'today':{'date':str(today),'store_total':today_total,'credited':today_credit,'historical':dayctx,'projection':proj},'challenge':challenge,'schedule':[dict(r) for r in sched]}

def clip_sync():
    raw_token=os.getenv('CLIP_TOKEN','').strip()
    api_key=os.getenv('CLIP_API_KEY','').strip()
    secret=os.getenv('CLIP_SECRET','').strip()
    if not raw_token and not api_key:
        return {'ok':False,'error':'Falta autenticación de Clip. Configura CLIP_TOKEN o CLIP_API_KEY + CLIP_SECRET en Render.'}
    if raw_token.lower().startswith(('basic ','bearer ')):
        auth_header=raw_token
    elif secret:
        key=api_key or raw_token
        auth_header='Basic '+base64.b64encode(f'{key}:{secret}'.encode('utf-8')).decode('ascii')
    else:
        key=api_key or raw_token
        auth_header='Bearer '+key

    ws,we=current_week(); endpoint='https://api-gw.payclip.com/payments'
    c=db(); s=c.execute("SELECT value FROM settings WHERE key='clip_endpoint'").fetchone(); c.close()
    if s: endpoint=s['value']
    start_local=datetime.combine(ws,time(0,0),TZ)
    start=start_local.astimezone(timezone.utc).isoformat().replace('+00:00','Z')
    end_utc=datetime.now(timezone.utc)
    end=end_utc.isoformat().replace('+00:00','Z')

    page=None; pages=0; api_count=0; seen_tokens=set()
    method_count={}; method_total={}; day_count={}; day_total={}
    first_local=None; last_local=None
    records={}

    for _ in range(50):
        params={'from':start,'to':end,'status':'paid','limit':'100'}
        if page: params['pagination_token']=page
        url=endpoint+'?'+urllib.parse.urlencode(params)
        req=urllib.request.Request(url,headers={'Authorization':auth_header,'Accept':'application/vnd.com.payclip.v2+json','Content-Type':'application/json'})
        try:
            with urllib.request.urlopen(req,timeout=20) as resp:
                data=json.loads(resp.read())
        except urllib.error.HTTPError as e:
            try: detail=e.read().decode('utf-8','replace')[:800]
            except Exception: detail=''
            return {'ok':False,'error':f'Clip respondió HTTP {e.code}: {e.reason}','detail':detail}
        except Exception as e:
            return {'ok':False,'error':f'No fue posible comunicarse con Clip: {e}'}

        pages += 1
        items=data.get('items') or data.get('payments') or data.get('results') or data.get('data') or []
        if isinstance(items,dict): items=items.get('items') or items.get('results') or []
        if not isinstance(items,list): items=[]
        api_count += len(items)

        for p in items:
            rid=str(p.get('receipt_no') or p.get('id') or '').strip()
            created=p.get('created_at') or p.get('approved_at') or p.get('created') or p.get('date')
            status=str(p.get('status') or '').strip().lower()
            method=str(p.get('payment_method') or 'UNKNOWN').strip().upper()
            raw_total=p.get('total')
            raw_amount=p.get('amount') or p.get('amount_received') or p.get('paid_amount') or 0
            if isinstance(raw_amount,dict): raw_amount=raw_amount.get('amount') or raw_amount.get('value') or 0
            if isinstance(raw_total,dict): raw_total=raw_total.get('amount') or raw_total.get('value')
            try: amount=float(raw_amount or 0)
            except: amount=0.0
            try: total=float(raw_total) if raw_total not in (None,'') else amount
            except: total=amount
            if not rid or not created: continue
            if status and status not in ('paid','approved'): continue
            try: ldt=parse_iso_dt(created)
            except: continue
            local_text=local_dt_text(ldt)
            local_day=local_text[:10]
            records[rid]=(local_text,total,method)
            first_local=min(first_local,local_text) if first_local else local_text
            last_local=max(last_local,local_text) if last_local else local_text

        next_page=(data.get('meta') or {}).get('pagination_token') or (data.get('pagination') or {}).get('next') or data.get('pagination_token') or data.get('next_pagination_token')
        if not next_page or not items or next_page==page or next_page in seen_tokens: break
        seen_tokens.add(next_page); page=next_page

    # Rebuild Clip transactions for the current week only after a successful full fetch.
    cc=db(); cur=cc.cursor()
    week_start_text=start_local.strftime('%Y-%m-%d %H:%M:%S')
    cur.execute("DELETE FROM transactions WHERE source='clip' AND ts>=?",(week_start_text,))
    for rid,(local_text,total,method) in records.items():
        cur.execute('INSERT OR REPLACE INTO transactions(external_id,ts,amount,status,source) VALUES(?,?,?,?,?)',(rid,local_text,total,'paid','clip'))
        d=local_text[:10]
        day_count[d]=day_count.get(d,0)+1
        day_total[d]=day_total.get(d,0.0)+total
        method_count[method]=method_count.get(method,0)+1
        method_total[method]=method_total.get(method,0.0)+total
    cc.commit(); cc.close()

    return {
        'ok':True,
        'imported':len(records),
        'api_count':api_count,
        'pages':pages,
        'sum_total':round(sum(day_total.values()),2),
        'day_count':dict(sorted(day_count.items())),
        'day_total':{k:round(v,2) for k,v in sorted(day_total.items())},
        'method_count':method_count,
        'method_total':{k:round(v,2) for k,v in method_total.items()},
        'query_from_utc':start,
        'query_to_utc':end,
        'first_local':first_local,
        'last_local':last_local,
        'synced_at':datetime.now(TZ).isoformat()
    }

class Handler(SimpleHTTPRequestHandler):
    def log_message(self, format, *args): pass
    def do_GET(self):
        p=urlparse(self.path)
        if p.path.startswith('/api/'):
            return self.api_get(p)
        if p.path=='/health':
            data=b'OK'; self.send_response(200); self.send_header('Content-Type','text/plain; charset=utf-8'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
        if p.path=='/': text=INDEX_HTML; ctype='text/html; charset=utf-8'
        elif p.path=='/admin': text=ADMIN_HTML; ctype='text/html; charset=utf-8'
        elif p.path=='/app.css': text=APP_CSS; ctype='text/css; charset=utf-8'
        else: self.send_error(404); return
        data=text.encode('utf-8'); self.send_response(200); self.send_header('Content-Type',ctype); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data)
    def do_POST(self):
        p=urlparse(self.path)
        try: body=read_json(self)
        except Exception as e: return json_out(self,{'error':str(e)},400)
        if p.path=='/api/login':
            pin=str(body.get('pin','')); name=str(body.get('name',''))
            c=db(); r=c.execute('SELECT id,name,pin_hash FROM employees WHERE name=? AND active=1',(name,)).fetchone(); c.close()
            if not r or r['pin_hash']!=hpin(pin): return json_out(self,{'error':'PIN incorrecto'},401)
            tok=secrets.token_urlsafe(24); SESSIONS[tok]={'eid':r['id'],'name':r['name'],'admin':False}; return json_out(self,{'ok':True},cookie='session='+tok)
        if p.path=='/api/admin/login':
            pin=str(body.get('pin','')); c=db(); r=c.execute("SELECT value FROM settings WHERE key='admin_pin_hash'").fetchone(); c.close()
            if not r or r['value']!=hpin(pin): return json_out(self,{'error':'PIN incorrecto'},401)
            tok=secrets.token_urlsafe(24); SESSIONS[tok]={'admin':True}; return json_out(self,{'ok':True},cookie='session='+tok)
        if p.path=='/api/logout': return json_out(self,{'ok':True},cookie='session=; Max-Age=0')
        if p.path=='/api/admin/save':
            if not auth(self,True): return json_out(self,{'error':'No autorizado'},401)
            ws=date.fromisoformat(body['week_start']); c=db(); cur=c.cursor()
            for t in body.get('targets',[]):
                cur.execute('INSERT OR REPLACE INTO weekly_targets(employee_id,week_start,target,bonus) VALUES(?,?,?,?)',(int(t['employee_id']),str(ws),float(t['target']),float(t.get('bonus',0))))
            # replace schedules only for submitted week
            cur.execute('DELETE FROM schedules WHERE work_date BETWEEN ? AND ?',(str(ws),str(ws+timedelta(days=6))))
            for s in body.get('schedules',[]):
                cur.execute('INSERT INTO schedules(employee_id,work_date,start_time,end_time) VALUES(?,?,?,?)',(int(s['employee_id']),s['work_date'],s['start_time'],s['end_time']))
            cur.execute('INSERT INTO audit(ts,action,detail) VALUES(?,?,?)',(datetime.now(TZ).isoformat(),'save_week',json.dumps({'week_start':str(ws)})))
            c.commit(); c.close(); return json_out(self,{'ok':True})
        if p.path=='/api/admin/manual-sale':
            if not auth(self,True): return json_out(self,{'error':'No autorizado'},401)
            ts=body.get('ts') or datetime.now(TZ).strftime('%Y-%m-%d %H:%M:%S'); amount=float(body.get('amount',0))
            if amount<=0: return json_out(self,{'error':'Importe inválido'},400)
            c=db(); c.execute('INSERT INTO transactions(external_id,ts,amount,status,source) VALUES(?,?,?,?,?)',(f'manual-{secrets.token_hex(8)}',ts,amount,'paid','manual')); c.commit(); c.close(); return json_out(self,{'ok':True})
        if p.path=='/api/admin/clip-sync':
            if not auth(self,True): return json_out(self,{'error':'No autorizado'},401)
            return json_out(self,clip_sync())
        return json_out(self,{'error':'Ruta no encontrada'},404)
    def api_get(self,p):
        if p.path=='/api/employees':
            c=db(); rows=c.execute('SELECT id,name FROM employees WHERE active=1 ORDER BY id').fetchall(); c.close(); return json_out(self,[dict(r) for r in rows])
        if p.path=='/api/me':
            s=auth(self); return json_out(self,{'authenticated':bool(s),'session':s or {}})
        if p.path=='/api/dashboard':
            s=auth(self)
            if not s or s.get('admin'): return json_out(self,{'error':'No autorizado'},401)
            return json_out(self,dashboard(s['eid']))
        if p.path=='/api/admin/week':
            if not auth(self,True): return json_out(self,{'error':'No autorizado'},401)
            qs=parse_qs(p.query); ws=current_week()[0]
            if qs.get('week_start'): ws=date.fromisoformat(qs['week_start'][0])
            we=ws+timedelta(days=6); c=db()
            emps=[dict(r) for r in c.execute('SELECT id,name FROM employees WHERE active=1 ORDER BY id')]
            targets=[dict(r) for r in c.execute('SELECT * FROM weekly_targets WHERE week_start=?',(str(ws),))]
            schedules=[dict(r) for r in c.execute('SELECT * FROM schedules WHERE work_date BETWEEN ? AND ? ORDER BY work_date,start_time',(str(ws),str(we)))]
            c.close(); cards=[]
            for e in emps:
                d=dashboard(e['id']); cards.append({'employee':e,'credited':d['week']['credited'],'target':d['week']['target'],'pct':d['week']['pct'],'remaining':d['week']['remaining'],'achieved':d['week']['achieved']})
            return json_out(self,{'week_start':str(ws),'week_end':str(we),'employees':emps,'targets':targets,'schedules':schedules,'cards':cards,'clip_configured':bool(os.getenv('CLIP_TOKEN','').strip())})
        if p.path=='/api/admin/history-summary':
            if not auth(self,True): return json_out(self,{'error':'No autorizado'},401)
            c=db(); rows=c.execute('SELECT weekday,COUNT(*) n,AVG(total) avg,MAX(total) max FROM daily_history GROUP BY weekday').fetchall(); c.close(); return json_out(self,[dict(r) for r in rows])
        return json_out(self,{'error':'Ruta no encontrada'},404)

def main():
    init_db()
    port=int(os.getenv('PORT','8765'))
    host=os.getenv('HOST','0.0.0.0')
    is_render=bool(os.getenv('RENDER'))
    display_host='localhost' if host in ('0.0.0.0','::') else host
    url=f'http://{display_host}:{port}/admin'
    print('='*68)
    print('COCO POPS PERFORMANCE - WEB')
    print('='*68)
    print(f'Servidor iniciado en {host}:{port}')
    print('Panel Dirección:', url)
    print('Panel colaborador: http://%s:%d' % (display_host,port))
    print('='*68)
    server=ThreadingHTTPServer((host,port),Handler)
    if not is_render and host in ('127.0.0.1','localhost'):
        threading.Timer(1.0, lambda: webbrowser.open(url)).start()
    server.serve_forever()

if __name__=='__main__':
    try:
        main()
    except KeyboardInterrupt:
        print('\nServidor detenido.')
    except Exception:
        print('\nERROR AL INICIAR COCO POPS PERFORMANCE')
        print('='*68)
        traceback.print_exc()
        try: input('\nPresiona ENTER para cerrar...')
        except Exception: pass

